-- Prepared forward migration only. No live enrollment or activation is performed.
-- The queue marker is sticky and is set only in the internal enrollment transaction.
CREATE TABLE IF NOT EXISTS hotel_journal_heads(queue_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,stage_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,baseline_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,generation INTEGER NOT NULL,control_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,owner_label VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,active_operation_id CHAR(64) CHARACTER SET ascii COLLATE ascii_bin,accepted_snapshot_id CHAR(64) CHARACTER SET ascii COLLATE ascii_bin,hold_reason VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin,PRIMARY KEY(queue_id,stage_id)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS hotel_journal_operations(operation_id CHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,queue_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,stage_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,generation INTEGER NOT NULL,event_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,task_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,state VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,capability_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,instance_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin,reported_run_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin,run_evidence_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin,candidate_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin,candidate_bytes LONGBLOB,native_effect VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,UNIQUE(queue_id,stage_id,generation,event_id)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS hotel_journal_requests(queue_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,stage_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,request_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,generation INTEGER NOT NULL,method VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,request_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,receipt_bytes LONGBLOB NOT NULL,PRIMARY KEY(queue_id,stage_id,request_id)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS hotel_journal_snapshots(snapshot_id CHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,queue_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,stage_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,operation_id CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,generation INTEGER NOT NULL,event_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,packet_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,body_bytes LONGBLOB NOT NULL,UNIQUE(queue_id,stage_id),UNIQUE(queue_id,packet_sha256)) ENGINE=InnoDB;

ALTER TABLE hotel_work_queues ADD COLUMN write_protocol VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'legacy';
